if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

const P1_RED_BRAND_LOGO_PNG = '';
const P1_RED_BRAND_ICON_PNG = '';

function p1_red_brand_logo_uri(): string {
	$file = WP_CONTENT_DIR . '/uploads/p1-red-logo-horizontal.png';
	$url = content_url( 'uploads/p1-red-logo-horizontal.png' );
	if ( ! file_exists( $file ) ) {
		file_put_contents( $file, base64_decode( P1_RED_BRAND_LOGO_PNG ) );
	}
	return $url;
}

function p1_red_brand_icon_uri(): string {
	return content_url( 'uploads/p1-nav-badge-1783343968900.png' ) . '?v=20260707-tab';
}

const P1_NAV_FRAME_TRANSPARENT_PNG = '';

function p1_red_brand_nav_frame_uri(): string {
	static $uri = null;

	if ( null !== $uri ) {
		return $uri;
	}

	// Transparent-center PNG: fins sit above nav, center is see-through for links.
	$uri = 'data:image/png;base64,' . P1_NAV_FRAME_TRANSPARENT_PNG;
	return $uri;
}

function p1_red_brand_custom_logo( string $html, int $blog_id ): string {
	unset( $blog_id );

	return sprintf(
		'<a href="%1$s" class="custom-logo-link" rel="home"><img width="520" height="120" src="%2$s" class="custom-logo p1-red-brand-logo" alt="%3$s" decoding="async" fetchpriority="high"></a>',
		esc_url( home_url( '/' ) ),
		esc_attr( p1_red_brand_logo_uri() ),
		esc_attr( get_bloginfo( 'name' ) ?: 'P1 Race Academy' )
	);
}
add_filter( 'get_custom_logo', 'p1_red_brand_custom_logo', 20, 2 );

function p1_red_brand_logo_attachment_attributes( array $attr, $attachment, $size ): array {
	unset( $attachment, $size );

	if ( empty( $attr['class'] ) || false === strpos( $attr['class'], 'custom-logo' ) ) {
		return $attr;
	}

	$attr['src']    = p1_red_brand_logo_uri();
	$attr['width']  = '520';
	$attr['height'] = '120';
	$attr['class'] .= ' p1-red-brand-logo';
	unset( $attr['srcset'] );

	return $attr;
}
add_filter( 'wp_get_attachment_image_attributes', 'p1_red_brand_logo_attachment_attributes', 20, 3 );

function p1_red_brand_site_icon_tags( array $meta_tags ): array {
	unset( $meta_tags );

	$icon = esc_url( p1_red_brand_icon_uri() );

	return [
		'<link rel="icon" href="' . $icon . '" sizes="512x512" type="image/png" />',
		'<link rel="apple-touch-icon" href="' . $icon . '" />',
		'<meta name="msapplication-TileImage" content="' . $icon . '" />',
	];
}
add_filter( 'site_icon_meta_tags', 'p1_red_brand_site_icon_tags', 20 );

function p1_red_brand_document_title(): string {
	return 'P1 Race Academy';
}
add_filter( 'pre_get_document_title', 'p1_red_brand_document_title', 1000 );

function p1_red_brand_document_title_parts( array $parts ): array {
	return [ 'title' => 'P1 Race Academy' ];
}
add_filter( 'document_title_parts', 'p1_red_brand_document_title_parts', 1000 );

